-- Seed Data Kontingen Kalteng
ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    short_code = EXCLUDED.short_code,
    logo_url = EXCLUDED.logo_url;

-- Seed Data Cabang Olahraga (Sesuai Jadwal Pelaksanaan PORPROV XIII/2026)
